const a="geopolitica-classica-tra-teologia-e-geopolitica-cina",e="geopolitica-classica/tra-teologia-e-geopolitica/cina",i="https://precious-cassata-42205a.netlify.app/geopolitica-classica/tra-teologia-e-geopolitica/cina",o="Caso Cina",u="02",t="La civiltà che ha sostituito il cielo con lo Stato: un primo studio sulla teologia politica implicita del Partito e il Mandato del Celeste Impero.",l="geopolitica-classica",r="geopolitica-classica/tra-teologia-e-geopolitica",n=[{type:"p",role:"label",runs:[{t:"02"}]},{type:"h",level:2,runs:[{t:"Caso Cina"}],role:"p"},{type:"p",role:"lede",runs:[{t:"La civiltà che ha sostituito il cielo con lo Stato: un primo studio sulla teologia politica implicita del Partito e il Mandato del Celeste Impero."}]},{type:"p",role:"p",runs:[{t:"«Il Partito ha sostituito il Mandato del Cielo: la legittimazione non viene più dall'alto, ma dalla promessa del futuro.»"}]},{type:"p",role:"p",runs:[{t:"MetaHistoria, Caso Cina"}]},{type:"p",role:"p",runs:[{t:"La Cina è il caso in cui la potenza materiale convive con un "},{t:"vuoto teologico artificiale",b:!0},{t:". Il confucianesimo, da religione civile imperiale, è stato spazzato via dal maoismo. Il maoismo, da religione politica, è stato spazzato via dal capitalismo di Stato. Oggi la Cina è un gigante con un sistema operativo teologico in modalità legacy: strutture vuote, riti senza fede."}]},{type:"p",role:"p",runs:[{t:"Eppure la Cina non è senza teologia: l'ha semplicemente "},{t:"secolarizzata nel Partito",b:!0},{t:". Il Mandato del Cielo l'antica dottrina che legittimava l'imperatore è stato trasferito al Partito Comunista. La storia non è più ciclica (dinastie che salgono e cadono) ma lineare: progresso, sviluppo, modernizzazione, sogno cinese."}]},{type:"p",role:"p",runs:[{t:"Dario Fabbri sottolineerebbe che la Cina si percepisce come "},{t:"civiltà",b:!0},{t:` prima che come Stato. Questa civiltà ha un centro (il celeste impero), una periferia (i regni tributari) e una missione: restaurare l'armonia universale. Il "Sogno Cinese" di Xi Jinping non è un programma economico: è un'`},{t:"escatologia politica",b:!0},{t:" il futuro restaurato come passato idealizzato."}]},{type:"p",role:"p",runs:[{t:"Il nemico non è un popolo, ma il "},{t:"caos",b:!0},{t:". L'Occidente è percepito come forza disgregante che introduce instabilità. La risposta cinese è il controllo totale: sorveglianza, repressione, armonia forzata. Il sacrificio richiesto è la libertà individuale in cambio di stabilità collettiva e grandezza nazionale."}]},{type:"h",level:3,runs:[{t:"Analisi per la griglia a quattro livelli"}],role:"p"},{type:"p",role:"p",runs:[{t:"1"}]},{type:"p",role:"p",runs:[{t:"Livello materiale"}]},{type:"p",role:"p",runs:[{t:"Superpotenza in ascesa",b:!0},{t:": seconda economia mondiale, esercito in modernizzazione, infrastrutture globali (Belt and Road), capacità tecnologica crescente. Demografia enorme ma in declino. Dipendenza energetica e vulnerabilità alimentari. Potenza materiale senza pari, ma con basi fragili."}]},{type:"p",role:"p",runs:[{t:"Il colosso economico cammina su gambe demografiche di argilla."}]},{type:"p",role:"p",runs:[{t:"2"}]},{type:"p",role:"p",runs:[{t:"Livello narrativo"}]},{type:"p",role:"p",runs:[{t:'"Sogno Cinese"',b:!0},{t:` restaurazione della centralità imperiale. La Cina si percepisce come civiltà, non come Stato-nazione. La narrazione del "secolo dell'umiliazione" (1839-1949) come trauma fondativo. La missione: ripristinare l'armonia universale sotto la guida cinese.`}]},{type:"p",role:"p",runs:[{t:"Una civiltà che si percepisce umiliata ma destinata a tornare al centro."}]},{type:"p",role:"p",runs:[{t:"3"}]},{type:"p",role:"p",runs:[{t:"Livello teologico implicito"}]},{type:"p",role:"p",runs:[{t:"Il"}]},{type:"p",role:"p",runs:[{t:"Il "},{t:"confucianesimo come religione civile",b:!0},{t:" è stato sostituito dal culto del Partito. Ma la struttura è la stessa: gerarchia, armonia, sacrificio individuale per il bene collettivo. Il Mandato del Cielo è ora il mandato della storia: il Partito governa perché realizza il progresso."}]},{type:"p",role:"p",runs:[{t:"L'antica teologia imperiale è stata secolarizzata, ma la sua forma è rimasta intatta."}]},{type:"p",role:"p",runs:[{t:"4"}]},{type:"p",role:"p",runs:[{t:"Livello escatologico"}]},{type:"p",role:"p",runs:[{t:'Escatologia secolarizzata del "Grande Rinnovamento"',b:!0},{t:`: la Cina tornerà al centro del mondo, come è sempre stato nei "cinque millenni di storia". Il futuro è la restaurazione del passato idealizzato. Non c'è aldilà: la grandezza nazionale è l'orizzonte ultimo.`}]},{type:"p",role:"p",runs:[{t:"Escatologia senza Dio: il paradiso è il passato restaurato come futuro."}]},{type:"p",role:"p",runs:[{t:"«La Cina è un gigante teologico muto: possiede tutta la potenza materiale del mondo, ma l'unica teologia che le resta è il culto del Partito. Quando un impero perde il suo sistema operativo teologico originario e non ne trova uno nuovo, diventa potenza senza anima e l'anima, prima o poi, si vendica.»"}]},{type:"p",role:"p",runs:[{t:"MetaHistoria, Caso Cina — Assioma"}]}],s=[],c=["C. Schmitt, Teologia politica (1922)","L. Caracciolo, Limes (1993 )","D. Fabbri, Geopolitica umana (2023)","Manifesto TGP-O (2026)"],p={blocks:29,chars:3516,hash:"70fe2f94e008d7b4140a03366f8c4477c56ab7d9c9d70f37c12a8473a1533854"},m={id:a,slug:e,sourceUrl:i,title:o,kicker:"02",lede:t,category:l,parentId:r,blocks:n,prevNext:s,references:c,stats:p};export{n as blocks,l as category,m as default,a as id,u as kicker,t as lede,r as parentId,s as prevNext,c as references,e as slug,i as sourceUrl,p as stats,o as title};
